#!/bin/sh
# Routed `check` — corpus/README.md index parity vs disk (knowledge/, lessons/, evidence/), both directions.
# Run from the lane root. Exit 0 iff no dangling in-scope index token and no uncovered file.
# Conventions: a backticked token is an index path when it starts with knowledge/, lessons/ or
# evidence/ (after stripping corpus/ or ../, a trailing / and a :N / :N-M suffix); * globs and
# {a,b} braces expand; an evidence/ file is covered by an ancestor evidence/ directory token.
exec python3 -c 'exec("import re,fnmatch,pathlib\nC=pathlib.Path(\"corpus\")\nT=re.findall(r\"`([^`\\n]+)`\",(C/\"README.md\").read_text())\nlits,pats=set(),set()\nfor t in T:\n    t=t.strip()\n    if not t or \" \" in t: continue\n    if t.startswith(\"../\"): t=t[3:]\n    if t.startswith(\"corpus/\"): t=t[7:]\n    t=re.sub(r\":\\d+(?:-\\d+)?$\",\"\",t).rstrip(\"/\")\n    if not t.startswith((\"knowledge/\",\"lessons/\",\"evidence/\")): continue\n    parts=[t]\n    while any(\"{\" in p for p in parts):\n        nxt=[]\n        for p in parts:\n            m=re.search(r\"\\{([^{}]+)\\}\",p)\n            nxt += [p[:m.start()]+a+p[m.end():] for a in m.group(1).split(\",\")] if m else [p]\n        parts=nxt\n    for p in parts:\n        (pats if (\"*\" in p or \"?\" in p) else lits).add(p)\nfiles=[p.relative_to(C).as_posix() for tr in (\"knowledge\",\"lessons\",\"evidence\") for p in (C/tr).rglob(\"*\") if p.is_file()]\ndang=[p for p in lits if not (C/p).exists()]+[p for p in pats if not any(fnmatch.fnmatch(f,p) for f in files)]\ndirs={p for p in lits if (C/p).is_dir()}\nmiss=[f for f in files if f not in lits and not any(fnmatch.fnmatch(f,p) for p in pats) and not (f.startswith(\"evidence/\") and any(f.startswith(d+\"/\") for d in dirs))]\nprint(\"dangling=%d missing=%d\"%(len(dang),len(miss)))\nfor d in dang: print(\"DANGLING\",d)\nfor m in miss: print(\"MISSING\",m)\nraise SystemExit(1 if (dang or miss) else 0)")'
